import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h=len(g); w=len(g[0]); out=[row[:] for row in g]
    # horizontal bars per row: min/max col of each color
    bars=[]
    for r in range(h):
        bycol={}
        for c in range(w):
            if g[r][c]: bycol.setdefault(g[r][c],[]).append(c)
        for col,cs in bycol.items():
            if len(cs)>=2: bars.append((r,min(cs),max(cs),col))
    maxbar=max(b[0] for b in bars) if bars else -1
    # marker columns: any nonzero below all bar rows
    mcols=set()
    for c in range(w):
        for r in range(maxbar+1,h):
            if g[r][c]: mcols.add(c)
    for c in mcols:
        gaps=[(r,col) for (r,cmin,cmax,col) in bars if cmin<c<cmax and g[r][c]==0]
        gaps.sort()
        top=0
        for r,colr in gaps:
            for rr in range(top,r+1): out[rr][c]=colr
            top=r+1
    return out

